pub const Status = struct {
    active: bool = false,
    __cp_dropped: bool = false,

pub fn show(what: []const u8, label: []const u8) Status {
            if (((!Output.isStderrTTY()) or (!Output.enable_ansi_colors_stderr))) {
                return Status{ .active = false };
            }
            var buf: [256]u8 = undefined;
            _ = &buf;
            const defanged = defang((&buf), label);
            _ = Output.printError("\x1b[2m{s} {s}…\x1b[0m\r", .{ what, defanged });
            _ = Output.flush();
            _ = status_shown.store(true, .monotonic);
            return Status{ .active = true };
    }

pub fn clear() void {
            if (status_shown.swap(false, .monotonic)) {
                _ = Output.printError("\x1b[2K\r", .{});
                _ = Output.flush();
            }
    }

pub fn __cp_deinit(self: *Status) void {
        if (self.__cp_dropped) return;
        self.__cp_dropped = true;
            if (self.active) {
                _ = Status.clear();
            }
    }
};

